export async function listTools() {
  return [
    {
      name: 'format_value',
      description: 'Format a value as text (uppercased) or integer (parsed base-10).',
      inputSchema: {
        type: 'object',
        properties: {
          value: { type: 'string', description: 'The value to format.' },
          kind: { type: 'string', enum: ['text', 'integer'], description: 'How to format the value.' },
        },
        required: ['value', 'kind'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'format_value') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }

  const allowed = new Set(['value', 'kind']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      const err = new Error(`Unknown argument: ${key}`);
      err.code = -32602;
      throw err;
    }
  }

  if (typeof args.value !== 'string') {
    const err = new Error('Argument "value" is required and must be a string');
    err.code = -32602;
    throw err;
  }

  if (args.kind !== 'text' && args.kind !== 'integer') {
    const err = new Error('Argument "kind" must be one of: text, integer');
    err.code = -32602;
    throw err;
  }

  let formatted;
  if (args.kind === 'text') {
    formatted = args.value.toUpperCase();
  } else {
    if (!/^[+-]?\d+$/.test(args.value.trim())) {
      const err = new Error(`Malformed integer: ${args.value}`);
      err.code = -32602;
      throw err;
    }
    formatted = String(parseInt(args.value, 10));
  }

  return {
    content: [{ type: 'text', text: formatted }],
  };
}

